#include <iostream>
#include <string>
using namespace std;

// Class definition
class Student {
private:
    string name;
    int rollNo;
    float marks;

public:
    // Member function to set data
    void setData(string n, int r, float m) {
        name = n;
        rollNo = r;
        marks = m;
    }

    // Member function to display data
    void display() {
        cout << "Name: " << name << endl;
        cout << "Roll No: " << rollNo << endl;
        cout << "Marks: " << marks << endl;
    }
};

int main() {
    // Create objects
    Student s1, s2;

    s1.setData("Yash", 101, 85.5);
    s2.setData("Riya", 102, 92.0);

    s1.display();
    cout << "---" << endl;
    s2.display();

    return 0;
}

#include <iostream>
using namespace std;

class Rectangle {
private:
    int length, width;

public:
    // 1. Default constructor
    Rectangle() {
        length = 0;
        width = 0;
        cout << "Default constructor called" << endl;
    }

    // 2. Parameterized constructor
    Rectangle(int l, int w) {
        length = l;
        width = w;
        cout << "Parameterized constructor called" << endl;
    }

    // 3. Copy constructor
    Rectangle(const Rectangle& other) {
        length = other.length;
        width = other.width;
        cout << "Copy constructor called" << endl;
    }

    // Destructor
    ~Rectangle() {
        cout << "Destructor called for (" << length << ", " << width << ")" << endl;
    }

    int area() { return length * width; }
};

int main() {
    Rectangle r1;           // default constructor
    Rectangle r2(5, 3);     // parameterized constructor
    Rectangle r3 = r2;      // copy constructor

    cout << "r1 area: " << r1.area() << endl;  // 0
    cout << "r2 area: " << r2.area() << endl;  // 15
    cout << "r3 area: " << r3.area() << endl;  // 15

    // Destructors called in reverse order: r3, r2, r1
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

// Base class
class Person {
protected:  // accessible in derived classes
    string name;
    int age;

public:
    void setPerson(string n, int a) {
        name = n;
        age = a;
    }
    void displayPerson() {
        cout << "Name: " << name << ", Age: " << age;
    }
};

// Derived class — inherits from Person
class Student : public Person {
private:
    int rollNo;
    float marks;

public:
    void setStudent(string n, int a, int r, float m) {
        setPerson(n, a);  // call base class method
        rollNo = r;
        marks = m;
    }

    void displayStudent() {
        displayPerson();  // call base class method
        cout << ", Roll: " << rollNo << ", Marks: " << marks << endl;
    }
};

int main() {
    Student s;
    s.setStudent("Yash", 20, 101, 85.5);
    s.displayStudent();
    // Output: Name: Yash, Age: 20, Roll: 101, Marks: 85.5
    return 0;
}

#include <iostream>
using namespace std;

// Base class
class Shape {
public:
    virtual void draw() {  // virtual function
        cout << "Drawing a generic shape" << endl;
    }
    virtual double area() = 0;  // pure virtual — abstract class
};

class Circle : public Shape {
    double radius;
public:
    Circle(double r) : radius(r) {}
    void draw() override {  // override base class virtual
        cout << "Drawing a circle" << endl;
    }
    double area() override {
        return 3.14159 * radius * radius;
    }
};

class Rectangle : public Shape {
    double length, width;
public:
    Rectangle(double l, double w) : length(l), width(w) {}
    void draw() override {
        cout << "Drawing a rectangle" << endl;
    }
    double area() override {
        return length * width;
    }
};

int main() {
    // Base class pointers pointing to derived class objects
    Shape* s1 = new Circle(5.0);
    Shape* s2 = new Rectangle(4.0, 6.0);

    s1->draw();  // Output: Drawing a circle (runtime dispatch!)
    cout << "Area: " << s1->area() << endl;  // 78.54

    s2->draw();  // Output: Drawing a rectangle
    cout << "Area: " << s2->area() << endl;  // 24.0

    delete s1;
    delete s2;
    return 0;
}
